import pandas as pd, numpy as np
def arx(files, na, nb, cols, dec=10, outs='Q'):
    Y=[];X=[]
    for f in files:
        d=pd.read_csv(f)[::dec]
        us={'V':d.voltage_pu.values,'Vs':d.voltage_setpoint_pu.values,'th':d.bus_angle_rad.values}
        y = d.reactive_power_pu.values if outs=='Q' else d.active_power_pu.values
        for k in range(max(na,nb),len(d)):
            row=[1]+[y[k-i] for i in range(1,na+1)]
            for c in cols: row+=[us[c][k-i] for i in range(0,nb+1)]
            X.append(row);Y.append(y[k])
    X=np.array(X);Y=np.array(Y); c,*_=np.linalg.lstsq(X,Y,rcond=None); return np.std(Y-X@c),c
